class Solution {
    public List<List<Integer>> verticalOrder(TreeNode root) {
        List<List<Integer>> res = new ArrayList<>();
        if (root == null) return res;
        Map<Integer, List<Integer>> cols = new HashMap<>();
        Queue<TreeNode> qNode = new LinkedList<>();
        Queue<Integer> qCol = new LinkedList<>();
        qNode.add(root); qCol.add(0);
        int minC = 0, maxC = 0;
        while (!qNode.isEmpty()) {
            TreeNode node = qNode.poll();
            int c = qCol.poll();
            cols.computeIfAbsent(c, k -> new ArrayList<>()).add(node.val);
            minC = Math.min(minC, c); maxC = Math.max(maxC, c);
            if (node.left != null) { qNode.add(node.left); qCol.add(c - 1); }
            if (node.right != null) { qNode.add(node.right); qCol.add(c + 1); }
        }
        for (int i = minC; i <= maxC; i++) if (cols.containsKey(i)) res.add(cols.get(i));
        return res;
    }
};

